import{_ as t,o,c as r,a2 as i}from"./chunks/framework.B2_yzPFF.js";const p=JSON.parse('{"title":"Security Policy","description":"","frontmatter":{},"headers":[],"relativePath":"security.md","filePath":"security.md","lastUpdated":null}'),d={name:"security.md"};function s(a,e,n,l,c,u){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="security-policy" tabindex="-1">Security Policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to &quot;Security Policy&quot;">​</a></h1><h2 id="supported-versions" tabindex="-1">Supported versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Supported</th></tr></thead><tbody><tr><td>3.x</td><td>Yes, security fixes land in the latest 3.x release</td></tr><tr><td>2.x and older</td><td>No</td></tr><tr><td>4.0.0 on npm</td><td>Not a release: published by mistake and deprecated; do not use</td></tr></tbody></table><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h2><p>Please do not open a public issue for security problems.</p><ol><li>Use GitHub&#39;s private vulnerability reporting: <strong>Security → Report a vulnerability</strong> on this repository. The report is visible only to the maintainers.</li><li>Include the affected version, a minimal reproduction, and the impact as you understand it.</li></ol><p>You will get an acknowledgement within <strong>3 business days</strong>. Confirmed vulnerabilities are fixed in a patch release as soon as possible; the target is <strong>14 days</strong> for high-severity issues. We will credit you in the release notes unless you prefer otherwise.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p><code>@mshindi-labs/refetch</code> is a thin client over native <code>fetch</code>. Reports we consider in scope include, for example:</p><ul><li>credentials or headers leaking to unintended origins (for example on redirects or through middleware)</li><li>unbounded resource use triggered by a hostile server (memory, retries, timers)</li><li>unsafe handling of response bodies or JSON</li><li>supply-chain issues in the published package or the release workflow</li></ul><p>Vulnerabilities in the runtime&#39;s <code>fetch</code> implementation itself should go to the respective runtime (Node.js, Bun, Deno, browsers).</p><h2 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h2><p>What the library defends against by default, and what it leaves to you:</p><table tabindex="0"><thead><tr><th>Threat</th><th>Default</th><th>Your part</th></tr></thead><tbody><tr><td>A bearer token sent to another origin through an absolute URL from untrusted data</td><td><code>withAuth</code> only attaches the token to the base URL&#39;s origin</td><td>Pass <code>origins</code> explicitly on instances without a <code>baseURL</code>; do not use <code>origins: &#39;any&#39;</code> with untrusted URLs</td></tr><tr><td>Custom credential headers (<code>X-API-Key</code>) following a cross-origin redirect</td><td>Not handled: <code>fetch</code> only strips <code>Authorization</code></td><td>Use <code>redirect: &#39;manual&#39;</code> or <code>&#39;error&#39;</code> when sending such headers</td></tr><tr><td>Memory exhaustion from an oversized or endless response</td><td>No cap unless <code>maxResponseSize</code> is set</td><td>Set <code>maxResponseSize</code> for untrusted servers</td></tr><tr><td>A hostile <code>Retry-After</code> parking a request</td><td>Capped by <code>maxRetryAfter</code> (60 s)</td><td>Lower it if needed</td></tr><tr><td>Prototype pollution through <code>__proto__</code> keys in JSON</td><td><code>JSON.parse</code> is used as is</td><td>Supply a hardened <code>parseJson</code> if bodies are merged into objects</td></tr><tr><td>Credentials in logs and error reports</td><td><code>response.request.headers</code> is redacted; thrown errors keep <code>request</code>, <code>response</code> and <code>headers</code> non-enumerable</td><td>Do not log <code>request.config</code>; scrub error bodies (<code>data</code>) if your API echoes secrets</td></tr><tr><td>CSRF in browsers</td><td><code>fetch</code> defaults are untouched (<code>credentials: &#39;same-origin&#39;</code>)</td><td>Protect state-changing endpoints server-side when using <code>credentials: &#39;include&#39;</code></td></tr></tbody></table><h2 id="supply-chain" tabindex="-1">Supply chain <a class="header-anchor" href="#supply-chain" aria-label="Permalink to &quot;Supply chain&quot;">​</a></h2><ul><li>Releases are published only from GitHub Actions through npm trusted publishing (OIDC) with provenance; no long-lived npm tokens exist.</li><li>Every release runs the full verification (<code>npm run ci</code>) before publishing.</li><li>Third-party actions are pinned to commit SHAs, and Dependabot keeps dependencies and actions current.</li><li>Verify a published version with <code>npm audit signatures</code> or by checking its provenance on npmjs.com.</li></ul>',16)])])}const b=t(d,[["render",s]]);export{p as __pageData,b as default};
